'use strict';

/**
* Copy a sequence of elements within a collection to another location in the same collection.
*
* @module @stdlib/utils/copy-within
*
* @example
* var copyWithin = require( '@stdlib/utils/copy-within' );
*
* var arr = [ 1, 2, 3, 4, 5 ];
* var out = copyWithin( arr, 0, 3 );
* // returns [ 4, 5, 3, 4, 5 ]
*
* arr = [ 1, 2, 3, 4, 5 ];
* out = copyWithin( arr, 0, 3, 4 );
* // returns [ 4, 2, 3, 4, 5 ]
*
* arr = [ 1, 2, 3, 4, 5 ];
* out = copyWithin( arr, -2, -3, -1 );
* // returns [ 1, 2, 3, 3, 4 ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
